import { Product } from '../../types';

const s = (
  idSuffix: string,
  name: string,
  baseName: string,
  sizeLabel: string,
  price: number,
  colour: string,
  dimensions: string,
  partCode?: string,
  unit: string = 'piece',
  image: string = '',
  images: string[] = []
): Product => {
  const gallery = images.length > 0 ? images : image ? [image] : [];
  return {
    id: `cera-${idSuffix}`,
    name,
    baseName,
    sizeLabel,
    category: 'plumbing',
    subcategory: 'Sanitaryware',
    price,
    unit,
    brand: 'Cera',
    fastDelivery: true,
    stockStatus: 'in_stock',
    stockCount: 50,
    sku: `CERA-${idSuffix.toUpperCase().replace(/[^A-Z0-9-]/g, '')}`,
    partCode,
    hsnCode: '6910',
    description: '',
    image: image || gallery[0] || '',
    images: gallery,
    specifications: {
      ...(colour && colour !== '-' ? { 'Colour / Finish': colour } : {}),
      ...(dimensions && dimensions !== '-' ? { Dimensions: dimensions } : {}),
    },
  };
};

